    expect(detect('/repo/a.js', content)).toEqual(['openai']);
  });
});

describe('library detector: Python', () => {
  it.each([
    ['import openai', ['openai']],
    ['import os, anthropic as ant', ['anthropic']],
    ['import torch.nn as nn', ['torch']],
    ['from openai import OpenAI', ['openai']],
    ['from langchain.chains import LLMChain', ['langchain']],
    ['from sklearn.model_selection import (\n    train_test_split,\n)', ['sklearn']],
    ['if USE_LLM:\n    import anthropic', ['anthropic']]
  ])('detects %j', (content, expected) => {
    expect(detect('/repo/app.py', content)).toEqual(expected);
  });

  it.each([
    ['import caretaker'],
    ['import openai_mock'],
    ['from . import openai'],
    ['from .openai import client'],
    ['# import openai'],
    ['"""\nimport openai\n"""'],
    ['raise RuntimeError("x") from openai_error']
  ])('ignores %j', (content) => {
    expect(detect('/repo/app.py', content)).toEqual([]);
  });

  it('reads code cells from notebooks', () => {
    const notebook = JSON.stringify({
      cells: [
        { cell_type: 'markdown', source: ['import torch\n'] },
        { cell_type: 'code', source: ['!pip install openai\n', 'from openai import OpenAI\n'] }
      ]
    });
    expect(detect('/repo/nb.ipynb', notebook)).toEqual(['openai']);
  });
});

describe('library detector: R', () => {
  it('detects library() calls but not prefixes or comments', () => {
    expect(detect('/repo/model.R', 'library(caret)\n# library(nnet)\nlibrary(caretEnsemble)')).toEqual([
      'caret'
    ]);
  });
});

describe('createLibraryDetector', () => {
  it('accepts custom library lists', () => {
    const content = "import { GoogleGenerativeAI } from '@google/generative-ai';\nimport OpenAI from 'openai';";
    expect(detect('/repo/a.ts', content, ['@google/generative-ai', 'cohere-ai'])).toEqual([
      '@google/generative-ai'
    ]);
  });

  it('matches `from pkg import sub` against dotted custom libraries', () => {
    expect(detect('/repo/a.py', 'from google import generativeai as genai', ['google.generativeai'])).toEqual([
      'google.generativeai'
    ]);
  });
});

describe('extractImports', () => {
  it('drops relative specifiers', () => {
    expect(extractImports("import a from './a';\nimport b from 'b';", 'x.js')).toEqual(['b']);
  });
});

describe('scanCodebase with LLM applications', () => {
  let tmpDir;

  afterEach(() => {
    if (tmpDir) fs.rmSync(tmpDir, { recursive: true, force: true });
    tmpDir = undefined;
  });

  it('detects the OpenAI-backed support triage demo', () => {
    const result = scanCodebase({ root: DEMO_DIR });
    const triage = path.join(DEMO_DIR, 'src', 'triage.js');
    expect(result.aiFiles).toContain(triage);
    expect(result.aiLibraryMatches[triage]).toEqual(['openai']);
  });

  it('scans .mjs, .cjs, .mts and .cts files', () => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-scan-ext-'));
    const files = {
      'a.mjs': "import OpenAI from 'openai';",
      'b.cjs': "const Anthropic = require('@anthropic-ai/sdk');",
      'c.mts': "import { ChatOpenAI } from '@langchain/openai';",
      'd.cts': "import Anthropic = require('@anthropic-ai/sdk');"
    };
    for (const [name, content] of Object.entries(files)) {
      fs.writeFileSync(path.join(tmpDir, name), content);
    }

    const result = scanCodebase({ root: tmpDir });

    expect(result.totalFiles).toBe(4);
    expect(result.aiLibraryMatches).toEqual({
      [path.join(tmpDir, 'a.mjs')]: ['openai'],
      [path.join(tmpDir, 'b.cjs')]: ['@anthropic-ai/sdk'],
      [path.join(tmpDir, 'c.mts')]: ['@langchain'],
      [path.join(tmpDir, 'd.cts')]: ['@anthropic-ai/sdk']
    });
  });

  it('throws when the root directory does not exist', () => {
    const missing = path.join(os.tmpdir(), 'frai-scan-does-not-exist-9f2c');
    expect(() => scanCodebase({ root: missing })).toThrow(/Cannot scan/);
  });
});

